package dev.psxlab.core;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;

public class XaControllerTest {
    @Test public void repeatedReadKeepsAlreadyDecodedSpeech(){try(Gpu g=new Gpu(false)){Bus b=ready(g,0x48,3,1,XaDecoderTest.sector(1,3,1));int buffered=b.cdrom.audioBufferedFrames();assertTrue(buffered>0);CdRomTest.command(b,6);assertEquals(buffered,b.cdrom.audioBufferedFrames());assertEquals(1,b.cdrom.xaSectors);}}
    private static Bus ready(Gpu gpu,int mode,int file,int channel,byte[] sector){Bus b=new Bus(gpu);b.cdrom.insert(new SectorSource(){public byte[] readSector(int at){return sector;}public int sectorCount(){return 1000;}});CdRomTest.command(b,0x0e,mode);CdRomTest.ack(b);CdRomTest.command(b,0x0d,file,channel);CdRomTest.ack(b);CdRomTest.command(b,6);CdRomTest.ack(b);CdRomTest.firstSector(b);return b;}
    @Test public void matchingXaIsDecodedWithoutDataIrqOrDma(){try(Gpu g=new Gpu(false)){Bus b=ready(g,0x48,3,1,XaDecoderTest.sector(1,3,1));assertEquals(1,b.cdrom.xaSectors);assertEquals(2352,b.cdrom.audioBufferedFrames());assertEquals(0,CdRomTest.irq(b));b.cdrom.write(3,128);assertEquals(0,b.cdrom.availableBytes());}}
    @Test public void mismatchedXaIsNotDecodedOrDeliveredAsData(){try(Gpu g=new Gpu(false)){Bus b=ready(g,0x48,3,1,XaDecoderTest.sector(1,3,2));assertEquals(0,b.cdrom.xaSectors);assertEquals(0,b.cdrom.audioBufferedFrames());assertEquals(0,CdRomTest.irq(b));}}
    @Test public void disabledDecoderLeavesRawXaAvailableAsData(){try(Gpu g=new Gpu(false)){Bus b=ready(g,32,3,1,XaDecoderTest.sector(1,3,1));assertEquals(0,b.cdrom.xaSectors);assertEquals(1,CdRomTest.irq(b));b.cdrom.write(3,128);assertEquals(2340,b.cdrom.availableBytes());}}
    @Test public void controllerVolumeChangesWaitForApplyThenSwapStereo(){try(Gpu g=new Gpu(false)){Bus b=ready(g,0x48,3,1,XaDecoderTest.sector(1,3,1));for(int i=0;i<100;i++)b.cdrom.audioFrame();b.cdrom.write(0,2);b.cdrom.write(2,0);b.cdrom.write(3,128);b.cdrom.write(0,3);b.cdrom.write(1,0);b.cdrom.write(2,128);int old=b.cdrom.audioFrame();assertEquals(14,(short)old,1);assertEquals(28,old>>16,2);b.cdrom.write(3,32);int swapped=b.cdrom.audioFrame();assertEquals(28,(short)swapped,2);assertEquals(14,swapped>>16,1);}}
    @Test public void muteConsumesAudioRatherThanReplayingItAfterDemute(){try(Gpu g=new Gpu(false)){Bus b=ready(g,0x48,3,1,XaDecoderTest.sector(1,3,1));CdRomTest.command(b,0x0b);CdRomTest.ack(b);int buffered=b.cdrom.audioBufferedFrames();assertEquals(0,b.cdrom.audioFrame());assertEquals(buffered-1,b.cdrom.audioBufferedFrames());CdRomTest.command(b,0x0c);CdRomTest.ack(b);for(int i=0;i<100;i++)b.cdrom.audioFrame();assertNotEquals(0,b.cdrom.audioFrame());}}
    @Test public void adpcmMuteAndFilterChangeResetAreEffective(){try(Gpu g=new Gpu(false)){Bus b=ready(g,0x48,3,1,XaDecoderTest.sector(1,3,1));b.cdrom.write(0,3);b.cdrom.write(3,1);assertEquals(0,b.cdrom.audioFrame());b.cdrom.write(3,0);for(int i=0;i<100;i++)b.cdrom.audioFrame();assertNotEquals(0,b.cdrom.audioFrame());CdRomTest.command(b,0x0d,3,2);assertEquals(0,b.cdrom.audioBufferedFrames());}}
    @Test public void mixedCdAudioBypassesVoiceMuteAndContinuesCaptureWhenDisabled(){try(Gpu g=new Gpu(false)){Bus b=ready(g,0x48,3,1,XaDecoderTest.sector(1,3,1));List<Short> out=new ArrayList<>();b.spu.setAudioSink((pcm,n)->{for(int i=0;i<n;i++)out.add(pcm[i]);});b.write16(0x1f801d80,0x3fff);b.write16(0x1f801d82,0x3fff);b.write16(0x1f801db0,0x7fff);b.write16(0x1f801db2,0x7fff);b.write16(0x1f801dac,4);b.write16(0x1f801daa,0x8001);b.spu.tick(768*100);b.spu.flushAudio();assertTrue(b.spu.cdMixedFrames>0);assertTrue(b.spu.cdNonzeroFrames>0);assertTrue(out.get(160)>10);assertTrue(out.get(161)>20);int remaining=b.cdrom.audioBufferedFrames();out.clear();b.write16(0x1f801daa,0xc000);b.spu.tick(768*100);b.spu.flushAudio();for(short sample:out)assertEquals(0,sample);assertEquals(remaining-100,b.cdrom.audioBufferedFrames());b.write16(0x1f801da6,0x20);assertTrue(b.spu.readTransfer()>10);}}
    @Test public void pauseDropsBufferedCdAudio(){try(Gpu g=new Gpu(false)){Bus b=ready(g,0x48,3,1,XaDecoderTest.sector(1,3,1));assertTrue(b.cdrom.audioBufferedFrames()>0);CdRomTest.command(b,9);assertEquals(0,b.cdrom.audioBufferedFrames());}}
    @Test public void queueIsBoundedForUnconsumedContinuousXa(){try(Gpu g=new Gpu(false)){Bus b=ready(g,0x48,3,1,XaDecoderTest.sector(1,3,1));for(int i=0;i<50;i++)b.cdrom.tick(CdRomTest.SECTOR);assertTrue(b.cdrom.audioBufferedFrames()<=32768);assertTrue(b.cdrom.xaDroppedFrames>0);}}
}
